import java.sql.*;
import javax.servlet.*;
import javax.servlet.http.*;
import java.util.logging.Logger;
import org.json.JSONObject;

public class AssetSearchServlet extends HttpServlet {
    private static final Logger log = Logger.getLogger(AssetSearchServlet.class.getName());
    private static final String DB_URL = System.getenv("JDBC_URL");
    private static final String DB_USER = System.getenv("DB_USER");
    private static final String DB_PASS = System.getenv("DB_PASS");

    @Override
    protected void doGet(HttpServletRequest req, HttpServletResponse resp)
            throws ServletException, java.io.IOException {
        String assetType = req.getParameter("type");
        String owner = req.getParameter("owner");
        String sortCol = req.getParameter("sort");
        String direction = req.getParameter("dir");

        // Input validation for sort direction
        if (direction == null || (!direction.equalsIgnoreCase("ASC") && !direction.equalsIgnoreCase("DESC"))) {
            direction = "ASC";
        }

        // Allowlist for sort columns
        String[] allowedSorts = {"asset_name", "created_at", "value", "owner_id"};
        boolean validSort = false;
        if (sortCol != null) {
            for (String col : allowedSorts) {
                if (col.equals(sortCol)) { validSort = true; break; }
            }
        }
        if (!validSort) sortCol = "created_at";

        // Build query with parameterized WHERE but dynamic ORDER BY
        StringBuilder sql = new StringBuilder();
        sql.append("SELECT asset_id, asset_name, asset_type, owner_id, value, created_at ");
        sql.append("FROM assets WHERE 1=1 ");

        if (assetType != null && !assetType.isEmpty()) {
            sql.append("AND asset_type = ? ");
        }
        if (owner != null && !owner.isEmpty()) {
            sql.append("AND owner_id = ? ");
        }

        // Sort column is validated above, direction is validated above
        sql.append("ORDER BY ").append(sortCol).append(" ").append(direction);

        // LIMIT injection point - developer forgot to validate/parameterize
        String limit = req.getParameter("limit");
        if (limit != null) {
            sql.append(" LIMIT ").append(limit);
        } else {
            sql.append(" LIMIT 100");
        }

        log.info("Executing asset search: sort=" + sortCol + " dir=" + direction);

        try (Connection conn = DriverManager.getConnection(DB_URL, DB_USER, DB_PASS);
             PreparedStatement stmt = conn.prepareStatement(sql.toString())) {

            int paramIdx = 1;
            if (assetType != null && !assetType.isEmpty()) {
                stmt.setString(paramIdx++, assetType);
            }
            if (owner != null && !owner.isEmpty()) {
                stmt.setString(paramIdx++, owner);
            }

            ResultSet rs = stmt.executeQuery();
            JSONObject result = new JSONObject();
            org.json.JSONArray assets = new org.json.JSONArray();

            while (rs.next()) {
                JSONObject asset = new JSONObject();
                asset.put("id", rs.getString("asset_id"));
                asset.put("name", rs.getString("asset_name"));
                asset.put("type", rs.getString("asset_type"));
                asset.put("owner", rs.getString("owner_id"));
                asset.put("value", rs.getDouble("value"));
                asset.put("created", rs.getTimestamp("created_at").toString());
                assets.put(asset);
            }

            result.put("assets", assets);
            result.put("count", assets.length());

            resp.setContentType("application/json");
            resp.setCharacterEncoding("UTF-8");
            resp.getWriter().write(result.toString());

        } catch (SQLException e) {
            log.severe("Database error: " + e.getMessage());
            resp.setStatus(500);
            resp.getWriter().write("{\"error\":\"internal error\"}");
        }
    }
}
